$ErrorActionPreference = "Stop"
$dir = "messages"
if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir | Out-Null }

function Write-Utf8NoBom {
    param([string]$Path, [string]$Content)
    $utf8NoBom = New-Object System.Text.UTF8Encoding($false)
    [System.IO.File]::WriteAllText($Path, $Content, $utf8NoBom)
    Write-Host "Wrote $Path"
}

# Each value below is Base64 of the UTF-8 JSON content.
# Storing it this way means this script file itself only ever
# contains plain ASCII characters, so it cannot be corrupted by
# codepage/encoding misdetection when PowerShell reads the script.
$b64 = @{}
$b64["it"] = ""
$b64["fr"] = ""
$b64["de"] = ""
$b64["nl"] = ""
$b64["et"] = ""
$b64["lv"] = ""
$b64["lt"] = ""
$b64["cs"] = ""
$b64["sk"] = ""
$b64["hu"] = ""
$b64["sl"] = ""
$b64["ro"] = ""
$b64["sr"] = ""
$b64["hr"] = ""
$b64["bg"] = ""
$b64["sq"] = ""
$b64["uk"] = ""
$b64["ru"] = ""
$b64["ka"] = ""
$b64["tr"] = ""
$b64["ja"] = ""
$b64["ko"] = ""
$b64["zh"] = ""
$b64["hi"] = ""
$b64["ms"] = ""
$b64["id"] = ""
$b64["tl"] = ""
$b64["he"] = ""
$b64["ar"] = ""
$b64["fa"] = ""

foreach ($code in $b64.Keys) {
    $bytes = [Convert]::FromBase64String($b64[$code])
    $jsonText = [System.Text.Encoding]::UTF8.GetString($bytes)
    $path = Join-Path $dir "$code.json"
    Write-Utf8NoBom -Path $path -Content $jsonText
}

Write-Host ""
Write-Host "Done. Created $($b64.Count) files in .\$dir\"